-- Isolated synthetic test schema ONLY; never migrate this into AVUQO production.
do $$
begin
 if not exists(select 1 from pg_roles where rolname='anon') then create role anon nologin; end if;
 if not exists(select 1 from pg_roles where rolname='authenticated') then create role authenticated nologin; end if;
 if not exists(select 1 from pg_roles where rolname='service_role') then create role service_role nologin; end if;
end $$;
create table public.sources(id uuid primary key,connector_key text unique not null,status text not null,sync_enabled boolean not null);
create table public.offers(id uuid primary key,source_id uuid not null references public.sources(id),source_offer_id text not null);
create table public.source_ingestion_items(id uuid primary key,source_id uuid not null references public.sources(id));
create table public.ebay_deletion_receipts(
 id bigint generated by default as identity primary key,
 notification_digest text not null unique check(notification_digest ~ '^[a-f0-9]{64}$'),
 user_id_digest text check(user_id_digest is null or user_id_digest ~ '^[a-f0-9]{64}$'),
 username_digest text check(username_digest is null or username_digest ~ '^[a-f0-9]{64}$'),
 eias_token_digest text check(eias_token_digest is null or eias_token_digest ~ '^[a-f0-9]{64}$'),
 state text not null default 'pending_privacy_review' check(state in ('pending_privacy_review','processing','completed','blocked')),
 first_received_at timestamptz not null default now(),completed_at timestamptz,
 constraint ebay_deletion_identifier_present check(
 user_id_digest is not null or username_digest is not null or eias_token_digest is not null)
);
-- The real versioned foundation migration creates the ownership mapping table.
create table public.price_history(
 id bigint generated by default as identity primary key,
 offer_id uuid not null references public.offers(id) on delete cascade,
 source_id uuid not null references public.sources(id)
);
create table public.product_matches(
 id uuid primary key,
 source_id uuid not null references public.sources(id),
 source_offer_id text not null
);
